INDEX_HTML = r'''
<!doctype html>
<html lang="ko">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>LOCAL_LLM Agent</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:#17202a;background:#eef2f5;line-height:1.5;--brand:#146c60;--line:#d9e2e6;--muted:#65737e;--panel:#fff;--soft:#f6f9fa}
*{box-sizing:border-box}body{margin:0;min-height:100vh}.app{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:100vh}.sidebar{background:#13211f;color:#eef8f6;padding:22px 16px;display:flex;flex-direction:column;gap:18px}.brand{font-size:19px;font-weight:800}.brand small{display:block;font-size:11px;letter-spacing:.12em;color:#8fc2b8;margin-bottom:4px}.new-chat{width:100%;border:1px solid #43625d;background:#1b302d;color:white;border-radius:10px;padding:11px;font-weight:700;cursor:pointer}.side-title{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:#89aaa4;margin:4px 4px 8px}.run-list{display:flex;flex-direction:column;gap:5px;overflow:auto}.run-item{border:0;background:transparent;color:#dce9e6;text-align:left;padding:9px 10px;border-radius:8px;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.run-item:hover{background:#203935}.side-footer{margin-top:auto;display:grid;gap:8px}.side-footer button{background:transparent;border:1px solid #43625d;color:#dce9e6;border-radius:9px;padding:9px;cursor:pointer}.main{min-width:0;display:flex;flex-direction:column;height:100vh}.topbar{height:64px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.92);display:flex;align-items:center;justify-content:space-between;padding:0 24px}.title{font-weight:750}.status{font-size:12px;border:1px solid var(--line);border-radius:999px;padding:6px 10px;background:#fff}.chat{flex:1;overflow:auto;padding:28px 24px 150px}.thread{max-width:880px;margin:0 auto}.welcome{padding:42px 12px;text-align:center;color:var(--muted)}.welcome h1{color:#1d2a30;font-size:28px;margin-bottom:8px}.message{display:flex;gap:12px;margin:20px 0}.avatar{width:32px;height:32px;border-radius:9px;display:grid;place-items:center;font-size:12px;font-weight:800;flex:0 0 auto}.user .avatar{background:#dfe8eb}.agent .avatar{background:#d8efe9;color:#0f6257}.bubble{max-width:760px;white-space:pre-wrap;overflow-wrap:anywhere}.user .bubble{background:#fff;border:1px solid var(--line);padding:12px 14px;border-radius:14px}.agent .bubble{padding:3px 0}.timeline{margin:12px 0 6px 44px;border-left:2px solid #dbe5e6;padding-left:14px}.step{position:relative;padding:8px 0}.step:before{content:"";position:absolute;left:-20px;top:15px;width:9px;height:9px;border-radius:50%;background:#8ca19d;border:3px solid #eef2f5}.step.ok:before{background:#208675}.step.warn:before{background:#bc7c1c}.step-title{font-size:13px;font-weight:750}.step-detail{font-size:12px;color:var(--muted);margin-top:2px}.artifact{display:inline-block;margin-top:7px;padding:7px 9px;border-radius:8px;background:#edf6f4;font-size:12px}.approval{margin:12px 0 8px 44px;padding:14px;border:1px solid #e4c88c;background:#fff9eb;border-radius:12px}.approval h4{margin:0 0 6px}.approval button,.feedback button,.drawer button{border:1px solid var(--line);background:#fff;border-radius:8px;padding:8px 11px;font-weight:650;cursor:pointer;margin-right:6px}.approval .approve{background:#176e62;color:#fff;border-color:#176e62}.feedback{margin:12px 0 0 44px}.feedback input{width:min(520px,100%);border:1px solid var(--line);border-radius:9px;padding:9px}.composer-wrap{position:fixed;left:250px;right:0;bottom:0;padding:18px 24px 24px;background:linear-gradient(transparent,#eef2f5 28%)}.composer{max-width:880px;margin:0 auto;background:white;border:1px solid #cbd8dc;border-radius:17px;padding:12px;box-shadow:0 12px 34px #18272d18}.composer textarea{width:100%;border:0;resize:none;min-height:58px;max-height:180px;font:inherit;outline:0;padding:6px 8px}.composer-row{display:flex;align-items:center;justify-content:space-between;gap:12px}.hint{font-size:12px;color:var(--muted)}.send{border:0;border-radius:10px;background:var(--brand);color:white;padding:10px 16px;font-weight:750;cursor:pointer}.send:disabled{opacity:.5}.drawer{position:fixed;right:0;top:0;width:min(420px,92vw);height:100vh;background:white;border-left:1px solid var(--line);box-shadow:-12px 0 35px #17272c18;padding:22px;z-index:20;overflow:auto;transform:translateX(100%);transition:.18s ease}.drawer.open{transform:translateX(0)}.drawer-head{display:flex;justify-content:space-between;align-items:center}.drawer h3{margin:18px 0 6px}.drawer pre{white-space:pre-wrap;background:var(--soft);border:1px solid var(--line);border-radius:9px;padding:10px;max-height:220px;overflow:auto}.drawer select{width:100%;padding:9px;border:1px solid var(--line);border-radius:9px}.details{margin-left:44px}.details summary{font-size:12px;color:var(--muted);cursor:pointer}.details pre{font-size:11px;white-space:pre-wrap;background:#f8fafb;border:1px solid var(--line);padding:10px;border-radius:8px}.error{color:#a13b32}.empty{font-size:13px;color:var(--muted)}
@media(max-width:780px){.app{grid-template-columns:1fr}.sidebar{display:none}.composer-wrap{left:0}.topbar{padding:0 14px}.chat{padding:18px 14px 145px}.timeline,.approval,.feedback,.details{margin-left:0}.welcome{padding-top:25px}}
</style>
</head>
<body>
<div class="app">
  <aside class="sidebar">
    <div class="brand"><small>LOCAL WORK AGENT</small>LOCAL_LLM</div>
    <button class="new-chat" onclick="newChat()">＋ 새 작업</button>
    <div><div class="side-title">최근 작업</div><div id="runList" class="run-list"><div class="empty">불러오는 중...</div></div></div>
    <div class="side-footer"><button onclick="toggleDrawer()">도구 · 설정</button></div>
  </aside>
  <main class="main">
    <header class="topbar"><div class="title" id="threadTitle">새 작업</div><div class="status" id="mode">연결 확인 중</div></header>
    <section class="chat" id="chat"><div class="thread" id="thread"><div class="welcome" id="welcome"><h1>무엇을 도와드릴까요?</h1><p>질문만 입력하세요. 관련 기억과 Skill을 확인하고 필요한 도구 실행까지 Agent가 이어서 처리합니다.</p></div></div></section>
  </main>
</div>
<div class="composer-wrap"><div class="composer"><textarea id="q" placeholder="예: experiment.txt를 읽고 과거 사례와 비교해서 Air Dome 이상 원인을 분석하고 보고서로 만들어줘"></textarea><div class="composer-row"><span class="hint" id="composerHint">자동 Skill 선택 · 변경 작업은 승인 후 실행</span><button class="send" id="send" onclick="runAgent()">보내기</button></div></div></div>
<aside class="drawer" id="drawer">
  <div class="drawer-head"><b>도구 · 설정</b><button onclick="toggleDrawer()">닫기</button></div>
  <h3>Skill</h3><select id="skill"><option value="">자동 선택</option></select>
  <h3>작업 폴더</h3><button onclick="openWorkspace()">폴더 열기</button><button onclick="showWorkspace()">파일 목록</button><pre id="workspace">-</pre>
  <h3>연결 진단</h3><button onclick="diagnose()">임베딩 진단</button><button onclick="reindex()">기억 재색인</button><pre id="diagnostic">-</pre>
  <h3>자기개선</h3><p class="empty">해결/실패 사례에서 knowledge candidate를 생성합니다.</p><button onclick="reflectNow()">Reflection 실행</button><pre id="reflection">-</pre>
</aside>
<script>
let currentId=null, currentRun=null, busy=false;
const toolNames={memory_search:'과거 기억 검색',list_files:'파일 목록 확인',read_file:'파일 읽기',write_file:'파일 생성',write_report:'보고서 생성',create_directory:'폴더 생성',run_command:'명령 실행',git_status:'Git 상태 확인',git_diff:'Git 변경 확인',git_log:'Git 기록 확인',git_commit:'Git 커밋',list_skills:'Skill 목록 확인',read_skill:'Skill 읽기',save_skill:'Skill 저장'};
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function scrollBottom(){document.getElementById('chat').scrollTop=document.getElementById('chat').scrollHeight}
function clearWelcome(){document.getElementById('welcome')?.remove()}
function addMessage(role,text){clearWelcome();const row=el('div','message '+role);row.appendChild(el('div','avatar',role==='user'?'YOU':'AI'));row.appendChild(el('div','bubble',text));document.getElementById('thread').appendChild(row);scrollBottom();return row}
function addTimeline(plan){const t=el('div','timeline');(plan||[]).forEach((x,i)=>{const s=el('div','step '+(i===0?'ok':''));s.appendChild(el('div','step-title',(i+1)+'. '+x));t.appendChild(s)});document.getElementById('thread').appendChild(t);scrollBottom();return t}
function renderRun(run, append=true){currentRun=run;currentId=run.conversation_id||currentId;document.getElementById('threadTitle').textContent=run.goal||'작업';if(!append){document.getElementById('thread').innerHTML='';addMessage('user',run.goal||'');}
 const timeline=el('div','timeline');(run.steps||[]).forEach((s,i)=>{const ok=!s.error;const st=el('div','step '+(ok?'ok':'warn'));const action=s.action||{};st.appendChild(el('div','step-title',(i+1)+'. '+(action.tool?(toolNames[action.tool]||action.tool):'재시도')));st.appendChild(el('div','step-detail',s.error||action.plan||((s.result&&s.result.verified===false)?'결과 검증 실패':'완료')));if(s.result&&s.result.artifact)st.appendChild(el('div','artifact','📄 '+s.result.artifact));timeline.appendChild(st)});document.getElementById('thread').appendChild(timeline);
 if(run.status==='awaiting_approval'){const box=el('div','approval');box.appendChild(el('h4','', '승인이 필요한 작업'));const p=run.pending_action||{};box.appendChild(el('div','step-detail',(toolNames[p.tool]||p.tool||'변경 작업')+' · '+JSON.stringify(p.arguments||{})));const a=el('button','approve','승인하고 계속');a.onclick=()=>continueAgent(run.id,'approve');const d=el('button','','거부');d.onclick=()=>continueAgent(run.id,'deny');box.append(a,d);document.getElementById('thread').appendChild(box)}
 if(run.answer){addMessage('agent',run.answer);addFeedback() } else if(run.error){addMessage('agent','실행 오류: '+run.error)} else if(run.status==='step_limit'){addMessage('agent','최대 실행 단계에 도달했습니다. 상세 로그를 확인해 주세요.')}
 const details=el('details','details');details.appendChild(el('summary','','상세 실행 로그'));details.appendChild(el('pre','',JSON.stringify(run,null,2)));document.getElementById('thread').appendChild(details);scrollBottom()}
function addFeedback(){if(!currentId)return;const box=el('div','feedback');const input=el('input');input.placeholder='실제 결과/메모 (선택)';input.id='note-'+currentId;box.appendChild(input);[['resolved','✓ 해결됨'],['failed','✕ 실패'],['important','★ 중요지식']].forEach(([v,t])=>{const b=el('button','',t);b.onclick=()=>feedback(v,input.value,b);box.appendChild(b)});document.getElementById('thread').appendChild(box)}
async function request(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error(await r.text());return r.json()}
async function runAgent(){if(busy)return;const q=document.getElementById('q'),question=q.value.trim();if(!question)return;busy=true;document.getElementById('send').disabled=true;document.getElementById('threadTitle').textContent=question.slice(0,42);addMessage('user',question);q.value='';let loading;
 try{const plan=await request('/api/agent/plan',{question,skill:document.getElementById('skill').value||null});loading=addTimeline(plan.steps);const d=await request('/api/agent/run',{question,skill:document.getElementById('skill').value||null});loading.remove();renderRun(d,true);await loadRuns()}catch(e){loading?.remove();addMessage('agent','오류가 발생했습니다. '+e.message)}finally{busy=false;document.getElementById('send').disabled=false}}
async function continueAgent(id,action){try{const d=await request('/api/agent/runs/'+id+'/'+action,{});document.getElementById('thread').innerHTML='';renderRun(d,false);await loadRuns()}catch(e){addMessage('agent','재개 실패: '+e.message)}}
async function feedback(status,note,button){if(!currentId)return;try{await request('/api/feedback/'+currentId,{status,note});button.textContent='저장됨';button.disabled=true}catch(e){button.textContent='저장 실패'}}
async function loadRuns(){try{const r=await fetch('/api/agent/runs?limit=18');const d=await r.json();const list=document.getElementById('runList');list.innerHTML='';if(!d.items.length){list.appendChild(el('div','empty','아직 작업이 없습니다'));return}d.items.forEach(run=>{const b=el('button','run-item',run.goal||'이름 없는 작업');b.title=run.status;b.onclick=()=>loadRun(run.id);list.appendChild(b)})}catch(e){document.getElementById('runList').textContent='불러오기 실패'}}
async function loadRun(id){const r=await fetch('/api/agent/runs/'+id);const d=await r.json();document.getElementById('thread').innerHTML='';renderRun(d,false)}
function newChat(){currentId=null;currentRun=null;document.getElementById('threadTitle').textContent='새 작업';document.getElementById('thread').innerHTML='<div class="welcome" id="welcome"><h1>무엇을 도와드릴까요?</h1><p>질문만 입력하세요. Agent가 기억 검색부터 실행과 검증까지 이어서 처리합니다.</p></div>';document.getElementById('q').focus()}
function toggleDrawer(){document.getElementById('drawer').classList.toggle('open')}
async function openWorkspace(){const d=await request('/api/workspace/open',{});document.getElementById('workspace').textContent=d.path||d.detail||'-'}
async function showWorkspace(){const r=await fetch('/api/workspace');const d=await r.json();document.getElementById('workspace').textContent=d.path+'\n'+(d.files||[]).join('\n')}
async function diagnose(){try{document.getElementById('diagnostic').textContent=JSON.stringify(await request('/api/diagnostics/embedding',{}),null,2)}catch(e){document.getElementById('diagnostic').textContent=e.message}}
async function reindex(){try{document.getElementById('diagnostic').textContent=JSON.stringify(await request('/api/embeddings/reindex',{}),null,2)}catch(e){document.getElementById('diagnostic').textContent=e.message}}
async function reflectNow(){const b=document.getElementById('reflection');b.textContent='분석 중...';try{const d=await request('/api/reflection',{});b.textContent='분석 case '+d.case_count+'개 / 생성 knowledge '+d.created.length+'개\n'+d.created.map(x=>'• '+x.rule+' ('+x.confidence+')').join('\n')}catch(e){b.textContent=e.message}}
document.getElementById('q').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();runAgent()}});
fetch('/health').then(r=>r.json()).then(d=>{document.getElementById('mode').textContent='● '+d.glm_mode+' · '+(d.approval_required?'승인 보호 ON':'승인 보호 OFF');document.getElementById('composerHint').textContent='자동 Skill 선택 · '+(d.approval_required?'변경 작업은 승인 후 실행':'승인 보호 꺼짐')}).catch(()=>document.getElementById('mode').textContent='서버 연결 오류');
fetch('/api/skills').then(r=>r.json()).then(d=>{(d.items||[]).forEach(s=>{const o=document.createElement('option');o.value=s.name;o.textContent=s.name;document.getElementById('skill').appendChild(o)})});
loadRuns();
</script>
</body>
</html>
'''
